syntax:
C++ syntax for constructors with potential name conflicts:

class Point3d {
private:
    float x;  // Member variable
    float y;
    float z;

public:
    Point3d(float x, float y, float z) {  // Parameters with same names as members
        this->x = x;  // Use 'this' to refer to member variable
        this->y = y;
        this->z = z;
    }  // Implementation note: 'this' is an implicit pointer of type Point3d*, pointing to the object's memory location. Alternatively, use member initializer lists for efficiency: Point3d(float x, float y, float z) : x(x), y(y), z(z) {};
